import{_ as i,l as n,o as e,c as o,v as t,p as s,x as r,d,i as h,S as m}from"./chunks/framework.InCnrqk-.js";const M=JSON.parse('{"title":"对角化与停机问题","description":"","frontmatter":{"title":"对角化与停机问题","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/halting-diagonalization.md","filePath":"cs/halting-diagonalization.md","lastUpdated":1789023840000}'),p={name:"cs/halting-diagonalization.md"};function A(_,a,g,T,c,u){const l=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="对角化与停机问题" tabindex="-1">对角化与停机问题 <a class="header-anchor" href="#对角化与停机问题" aria-label="Permalink to &quot;对角化与停机问题&quot;">​</a></h1><div class="epigraph"><p>假定有判定机回答「$M$ 是否接受 $w$」，把它接到自己的编码上再翻转，就会矛盾；停机与接受一样不可判定。</p><footer>—— 据 Turing, 1936；Sipser 整理</footer></div><p>上一课<a href="/cs/decidable-recognizable">可判定与可识别</a>给出 \\(A_{\\mathrm{TM}}\\) 可识别，并留下是否可判定。缺口是<strong>对角化</strong>：通用机让 \\(\\langle M\\rangle\\) 成为串，自指加翻转推出没有判定器。本课同时写下停机问题 \\(HALT\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>假设 \\(H\\) 判定 \\(A_{\\mathrm{TM}}\\)。构造 \\(D(\\langle M\\rangle)\\)：跑 \\(H(\\langle M,\\langle M\\rangle\\rangle)\\)，若 \\(H\\) 说接受则拒绝，否则接受。问 \\(D(\\langle D\\rangle)\\)：两种答案都反。故 \\(H\\) 不存在。\\(A_{\\mathrm{TM}}\\) 仍可识别（模拟到接受为止），于是这是严格的 RE \\(\\setminus\\) 可判定。</p><p>停机 \\(HALT=\\{\\langle M,w\\rangle\\mid M\\) 在 \\(w\\) 上停}$。若 \\(HALT\\) 可判定，模拟到停再看是否接受，就判定了 \\(A_{\\mathrm{TM}}\\)。故 \\(HALT\\) 不可判定。识别 \\(HALT\\)：模拟，\\(M\\) 停则接受。</p><h3 id="对角化不是基数游戏的全部" tabindex="-1">对角化不是基数游戏的全部 <a class="header-anchor" href="#对角化不是基数游戏的全部" aria-label="Permalink to &quot;对角化不是基数游戏的全部&quot;">​</a></h3><p>\\(\\Sigma^*\\) 可数，语言不可数，故存在不可识别语言。对角化给出<strong>具体</strong>的不可判定语言，而且仍 RE。纯基数不给出 \\(A_{\\mathrm{TM}}\\)。</p><p><span class="marginnote"> Turing 1936 证明判定问题无解。课堂把接受问题与停机问题分成两个语言。Cantor 对角化是同一手法在 \\(\\{0,1\\}^{\\mathbb{N}}\\) 上；这里翻的是「第 \\(M\\) 台机器在输入 \\(\\langle M\\rangle\\) 上」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写清 \\(D\\) 的构造与矛盾的两分支。强调 \\(H\\) 必须总停，否则 \\(D\\) 的「若」没有定义。识别器不能这样翻：否实例上循环，翻转无法在有限步完成。</p>',11)),(e(),s(m,null,{default:r(()=>[h(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%81%87%E8%AE%BE%20H%20%E5%88%A4%E5%AE%9A%20A_TM%22%5D%20--%5Cgt%20%20D%5B%22D%20%E7%BF%BB%E8%BD%AC%20H%20%E5%9C%A8%20%E2%9F%A8M%2C%E2%9F%A8M%E2%9F%A9%E2%9F%A9%22%5D%0A%20%20D%20--%5Cgt%20%20CONTR%5B%22D%E2%9F%A8D%E2%9F%A9%20%E7%9F%9B%E7%9B%BE%22%5D%0A%20%20CONTR%20--%5Cgt%20%20UNDEC%5B%22A_TM%20%E4%B8%8D%E5%8F%AF%E5%88%A4%E5%AE%9A%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不要把「程序员看不出来会不会停」当成证明：那是经验，对角化是存在性矛盾。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>通用模拟让机器空间可编码、可复制。后课映射归约把其他问题化到 \\(A_{\\mathrm{TM}}\\) 或 \\(HALT\\)，不必每次再造一个 \\(D\\)。本课只打两颗钉子。Rice 将把「语义性质」一批送走。</p><p>时间有限的截断不能判定停机：给不出对所有 \\(M,w\\) 都够用的步数界。</p><p>通用机 \\(U(\\langle M,w\\rangle)\\) 模拟 \\(M\\) 于 \\(w\\)，自身必须能编码。对角化攻击的是「判定一切机器」的 \\(H\\)，不是某一台具体程序——静态分析可以对子类停机。Busy Beaver 函数增长快过一切可计算函数，是同一不可判定性的定量版，本课不展开。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Busy Beaver 不可计算，不引入神谕层级。不把停机写成「死循环检测工具做不到」的工程句——静态分析可以在子类上停，全类不行。后课默认：\\(A_{\\mathrm{TM}}\\)、\\(HALT\\) 不可判定、可识别。下一课映射归约传递不可判定性。</p><p>识别器不能对角翻转，因为否实例上可能循环，\\(D\\) 的「否则接受」没有有限步定义。这正是可判定与可识别的差别变成具体语言 \\(A_{\\mathrm{TM}}\\) 的地方。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对角化：翻转通用判定器，打掉 \\(A_{\\mathrm{TM}}\\)。</li><li>\\(HALT\\) 与 \\(A_{\\mathrm{TM}}\\) 同样不可判定，仍可识别。</li><li>识别器无法同样翻转，因为可能循环。</li><li>出处：Turing, 1936；Sipser。</li></ul>',10))])}const D=i(p,[["render",A]]);export{M as __pageData,D as default};
